"""C5: close_case input checks and error handling, plus case_creator after a close (no Docker needed)."""
import json, unittest
from decimal import Decimal
from unittest import mock

from botocore.exceptions import ClientError

from consumers import run
from scripts import close_case as cc

CASE, T0 = "tok_1#1793955000000", 1793955000.0


def err(code):
    return ClientError({"Error": {"Code": code}}, "Write")


class Inputs(unittest.TestCase):
    def test_accepts_real_case(self):
        self.assertTrue(cc.valid_case_id(CASE))

    def test_rejects_other_rows(self):
        for bad in ("card#tok_1", "evt#3f2a-11", "tok_1#12", CASE + " OR 1=1", "", None):
            self.assertFalse(cc.valid_case_id(bad), bad)


class CloseSteps(unittest.TestCase):
    def test_condition_failure_is_refused(self):
        t = mock.Mock(**{"update_item.side_effect": err("ConditionalCheckFailedException")})
        with self.assertRaises(cc.CloseRefused):
            cc.close(t, CASE, "fraud", "a.analyst", 0)

    def test_other_errors_propagate(self):
        t = mock.Mock(**{"update_item.side_effect": err("ThrottlingException")})
        with self.assertRaises(ClientError):
            cc.close(t, CASE, "fraud", "a.analyst", 0)

    def test_newer_pointer_left_alone(self):
        t = mock.Mock(**{"delete_item.side_effect": err("ConditionalCheckFailedException")})
        cc.release_pointer(t, "tok_1", CASE)           # must not raise

    def test_label_deterministic_and_minimal(self):
        s3 = mock.Mock()
        case = {"case_id": CASE, "card_token": "tok_1", "outcome": "fraud", "txn_ids": {"b", "a"},
                "closed_by": "a.analyst", "closed_at": Decimal(5)}
        cc.write_label(s3, case)
        cc.write_label(s3, case)
        first, second = (c.kwargs for c in s3.put_object.call_args_list)
        self.assertEqual(first, second)                 # rerun writes the identical file
        self.assertEqual(first["Key"], "dispositions/tok_1_1793955000000.json")
        self.assertEqual(json.loads(first["Body"])["txn_ids"], ["a", "b"])


class CreatorAfterClose(unittest.TestCase):
    def test_flag_after_close_opens_new_case(self):
        t = mock.Mock()
        t.get_item.side_effect = [{}, {"Item": {"open_case_id": CASE, "last_flag_ts": Decimal(str(T0))}}]
        t.update_item.side_effect = [err("ConditionalCheckFailedException"), None, None]  # old case closed
        evt = {"decision": "DECLINE", "card_token": "tok_1", "event_id": "e1", "score": 0.9}
        with mock.patch.object(run, "cases", t), mock.patch.object(run, "_ts", return_value=T0 + 60):
            run.case_creator(evt)
        new_id = run.new_case_id("tok_1", T0 + 60)
        self.assertEqual(t.update_item.call_args_list[1].kwargs["Key"], {"case_id": new_id})
        t.put_item.assert_called_once_with(Item={"case_id": "evt#e1", "case": new_id})


if __name__ == "__main__":
    unittest.main()
